{
  "claim_reviews": [
    {"claim": 1, "verdict": "accept", "reason": "Correctly states the Berta et al. (2010) EUR-QM with the squared overlap parameter c = max|⟨x_i|z_j⟩|² and the inequality S(X|B) + S(Z|B) ≥ log₂(1/c) + S(A|B) = -2 log₂(max|⟨x_i|z_j⟩|) + S(A|B). Exact citation (Nature Physics 6, 659–662, arXiv:0909.0950) is accurate. Type=verifiable is correct for a mathematical theorem. Confidence 0.98 is appropriate."},
    {"claim": 2, "verdict": "accept", "reason": "Accurately describes the purification derivation: purification |ψ⟩_ABE, data-processing inequality, duality S(X|B) = -S(X|E) for pure tripartite states, yielding the tripartite lemma S(X|B) + S(Z|E) ≥ log₂(1/c) which directly gives the bipartite form. Correctly avoids claiming 'equivalence' between bipartite and tripartite forms. Type=verifiable, confidence 0.96 appropriate."},
    {"claim": 3, "verdict": "accept", "reason": "Correctly restricts the original 2010 paper to finite-dimensional Hilbert spaces and attributes continuous-variable extensions to Furrer et al. (2012, PRL 109, 100502) and the 2013/2014 work (arXiv:1308.4527). Limit behaviors (maximally entangled case S(A|B) = -log₂(d_A), MUBs c=1/d_A giving zero bound, trivial B recovering Maassen-Uffink) are correctly stated. Type=verifiable, confidence 0.96 appropriate."},
    {"claim": 4, "verdict": "accept", "reason": "Correctly cites the three key tightenings: (a) Pati et al. 2012 (PRA 86, 042105, arXiv:1111.0984) on quantum discord/classical correlations; (b) Coles & Piani 2014 (PRL 113, 030402, arXiv:1402.7197) on secondary overlaps/state entropy; (c) Coles, Berta, Tomamichel, Wilde, Wehner 2015/2017 (Rev. Mod. Phys. 89, 015002, arXiv:1511.04857) on unified relations with measurement reversibility/disturbance. Correctly states tightenings add non-negative state-dependent terms. Type=verifiable, confidence 0.96 appropriate."},
    {"claim": 5, "verdict": "accept", "reason": "Clearly distinguishes: (a) standard BB84/six-state QKD security using EUR-QM with trusted/characterized devices; (b) DI-QKD and SDI-QKD as distinct frameworks with relaxed trust assumptions also using EUR-QM; (c) entropic uncertainty violations as witnesses for entanglement/steering. Avoids conflation of trust assumptions. Type=verifiable, confidence 0.95 appropriate."}
  ],
  "update_reviews": [
    {"update": 1, "agree": true, "reason": "F0089 correctly superseded by claim 1, which fixes the overlap parameter definition (squared overlap) and factor-of-2 error."},
    {"update": 2, "agree": true, "reason": "F0090 correctly superseded by claim 2, which clarifies the tripartite form as a proof lemma without false equivalence claim."},
    {"update": 3, "agree": true, "reason": "F0091 correctly superseded by claim 3, which restricts domain to finite-dimensional and attributes CV extensions to Furrer et al. (2012) and subsequent work."},
    {"update": 4, "agree": true, "reason": "F0092 correctly superseded by claim 4, which corrects paper titles, authors, DOIs, and arXiv identifiers for all three tightenings."},
    {"update": 5, "agree": true, "reason": "F0093 correctly superseded by claim 5, which properly distinguishes standard QKD from DI-QKD/SDI-QKD trust assumptions."}
  ],
  "task_complete": true,
  "appeal_check": "No claim appears shaped to impress. All five claims are precise, technical corrections of mathematical definitions, proof logic, domain boundaries, citations, and framework distinctions — exactly as requested.",
  "disagreements": [],
  "next_step": "All five corrected findings are accepted. The knowledge base now has sound, uncontested findings for F0089–F0093. Proceed to next planned tasks in M3 or M2."
}
